// Week 8 Mawhiba deck: Unit 2 Activity 4 (Sequences generated by repeated application of a linear function).
// Same Prezi-style journey as the Week 6 Mawhiba deck. Run: node buildmaw8.js  (then python3 morph8.py)
const pptxgen=require('pptxgenjs');
const IDX=require('./mw10/_index.json');
const NOTES={a1:require('./notes10.json')};
const L='./';
const C={NAVY:'1F3864',INK:'222E2D',TEAL:'17A199',DEEP:'0E4F4C',OR:'E8762C',GOLD:'F0B323',BG:'F4F8F7',WHITE:'FFFFFF'};
const FONT='Calibri', HEAD='Cambria';
const sh=()=>({type:'outer',color:'000000',opacity:0.15,blur:8,offset:2,angle:90});

function build(cfg){
 const pres=new pptxgen(); pres.layout='LAYOUT_WIDE'; pres.title=cfg.file; pres.author='Mr Malek Thiab';
 const ST=cfg.stations, K=ST.length; let N=0;
 const CODES='MAWHIBA GRADE 9  ·  WEEK 10  ·  UNIT 3  ·  ACTIVITY '+cfg.act;
 const txt=(s,t,o)=>s.addText(t,Object.assign({fontFace:FONT,color:C.INK,fontSize:16,margin:0,isTextBox:true,valign:'top'},o));
 const M=(s,key,x,y,sc=1.6,maxW=99)=>{const m=IDX[key]; if(!m) throw new Error('no math '+key); sc=Math.min(sc,maxW/m.win); const w=m.win*sc,h=m.hin*sc; s.addImage({path:'mw10/'+key+'.png',x,y,w,h}); return {w,h};};
 const Mc=(s,key,cx,y,sc,maxW)=>{const m=IDX[key]; sc=Math.min(sc,maxW/m.win); return M(s,key,cx-m.win*sc/2,y,sc,maxW);};
 const card=(s,x,y,w,h,fill=C.WHITE,line)=>s.addShape('roundRect',{x,y,w,h,rectRadius:0.12,fill:{color:fill},line:line?{color:line,width:1.25}:{color:'DDE6E4',width:0.75},shadow:sh()});
 const lab=(s,t,x,y,w=4,col=C.OR)=>txt(s,t,{x,y,w,h:0.25,fontSize:11,bold:true,color:col,charSpacing:2});
 const bullets=(a,fs=15,gap=6)=>a.map((t,i)=>({text:t,options:{bullet:true,breakLine:i<a.length-1,paraSpaceAfter:gap}}));
 const numbered=(a,gap=6)=>a.map((t,i)=>({text:t,options:{bullet:{type:'number'},breakLine:i<a.length-1,paraSpaceAfter:gap}}));

 const chips=(s,codes)=>{ return; codes.forEach((k,i)=>{const [t,fc,tc]=SK[k]; const x=12.85-(codes.length-i)*1.2; s.addShape('roundRect',{x,y:0.98,w:1.12,h:0.27,rectRadius:0.13,fill:{color:fc},line:{color:C.WHITE,width:1}}); txt(s,t,{x,y:0.98,w:1.12,h:0.27,fontSize:9,bold:true,color:tc,align:'center',valign:'middle',charSpacing:1});});};
 const whatif=(s,x,y,w,h,text,key,sc=1.5,imgW=2.4)=>{ s.addShape('roundRect',{x,y,w,h,rectRadius:0.12,fill:{color:'FFF1C9'},line:{color:C.GOLD,width:2.25},shadow:sh()});
   let tw=w-0.5; if(key){const m=IDX[key]; const k2=Math.min(sc,imgW/m.win); const iw=m.win*k2, ih=m.hin*k2; s.addImage({path:'mw10/'+key+'.png',x:x+w-0.25-iw,y:y+h/2-ih/2+0.18,w:iw,h:ih}); tw=w-0.5-iw-0.15;}
   txt(s,'WHAT IF...?',{x:x+0.25,y:y+0.12,w:3,h:0.28,fontSize:12,bold:true,color:C.OR,charSpacing:2}); txt(s,text,{x:x+0.25,y:y+0.45,w:tw,h:h-0.55,fontSize:14,color:C.INK});};
 const circles=(s)=>{s.addShape('ellipse',{x:-1.2,y:5.2,w:3.4,h:3.4,fill:{color:C.TEAL,transparency:88},line:{color:C.TEAL,transparency:100}});
   s.addShape('ellipse',{x:11.2,y:-1.3,w:3.2,h:3.2,fill:{color:C.GOLD,transparency:86},line:{color:C.GOLD,transparency:100}});};
 const chrome=(s,dark)=>{
  s.addImage({path:L+(dark?'dept_logo_white.png':'dept_logo.png'),x:0.4,y:0.22,w:1.62,h:0.5});
  s.addImage({path:L+(dark?'school_logo_white.png':'school_logo.png'),x:12.35,y:0.18,w:0.62,h:0.62});
  txt(s,CODES,{x:0.4,y:7.1,w:5.2,h:0.25,fontSize:8.5,color:dark?'BFD8D5':'5A6B69'});
  txt(s,'FAITH, RIGHTEOUSNESS AND WISDOM',{x:5.6,y:7.1,w:3.8,h:0.25,fontSize:10,bold:true,color:dark?'FFFFFF':C.NAVY,align:'center',charSpacing:3});
  txt(s,'Mr Malek Thiab  ·  '+N,{x:9.6,y:7.1,w:3.35,h:0.25,fontSize:10,color:dark?'BFD8D5':'5A6B69',align:'right'});};
 const crumb=(s,active)=>{const x0=7.2-K*0.39+0.4;
  for(let i=0;i<K;i++){const on=i===active,d=on?0.5:0.3,cx=x0+i*0.78,cy=0.5;
   s.addShape('ellipse',{objectName:'stn'+(i+1),x:cx-d/2,y:cy-d/2,w:d,h:d,fill:{color:on?C.OR:C.TEAL},line:{color:C.WHITE,width:1.5}});
   txt(s,String(i+1),{x:cx-0.2,y:cy-0.12,w:0.4,h:0.24,fontSize:on?12:9,bold:true,color:C.WHITE,align:'center',valign:'middle'});
   if(i<K-1) s.addShape('line',{objectName:'path'+(i+1),x:cx+d/2+0.02,y:cy,w:0.78-d/2-(i+1===active?0.25:0.15)-0.02,h:0,line:{color:C.TEAL,width:2,dashType:'dash'}});}};
 const slide=(title,st,notes)=>{N++; const s=pres.addSlide(); s.background={color:C.BG}; circles(s); chrome(s,false);
  if(st!==null&&st!==undefined) crumb(s,st);
  if(title){ if(st!==null&&st!==undefined) txt(s,('STATION '+(st+1)+'  ·  '+ST[st][0]+'  ·  '+ST[st][1]).toUpperCase(),{x:0.5,y:0.98,w:9,h:0.3,fontSize:12,bold:true,color:C.OR,charSpacing:2});
   txt(s,title,{x:0.5,y:1.25,w:12.3,h:0.6,fontSize:30,bold:true,fontFace:HEAD,color:C.NAVY,valign:'middle'});}
  s.addNotes(notes); return s;};
 const stationMap=(s,done)=>{ // journey circles, K stations
  const D=1.45, gap=(12.4-1.5)/(K-1); const cx=[],cy=[]; for(let i=0;i<K;i++){cx.push(1.5+i*gap); cy.push(i%2===0?4.7:3.5);}
  for(let i=0;i<K-1;i++){const x1=cx[i],y1=cy[i],x2=cx[i+1],y2=cy[i+1]; s.addShape('line',{objectName:'path'+(i+1),x:x1,y:Math.min(y1,y2),w:x2-x1,h:Math.abs(y2-y1),flipV:y2<y1,line:{color:C.GOLD,width:3,dashType:'dash'}});}
  for(let i=0;i<K;i++){ s.addShape('ellipse',{objectName:'stn'+(i+1),x:cx[i]-D/2,y:cy[i]-D/2,w:D,h:D,fill:{color:done?C.GOLD:(i===0?C.OR:C.TEAL)},line:{color:C.WHITE,width:3}});
   txt(s,done?'✓':String(i+1),{x:cx[i]-0.4,y:cy[i]-0.3,w:0.8,h:0.6,fontSize:done?32:30,bold:true,fontFace:HEAD,color:done?C.DEEP:C.WHITE,align:'center',valign:'middle'});
   const above=cy[i]<4; txt(s,done?ST[i][0]:ST[i][0]+'\n'+ST[i][1],{x:cx[i]-1.1,y:above?cy[i]-D/2-(done?0.7:0.95):cy[i]+D/2+0.12,w:2.2,h:done?0.6:0.8,fontSize:done?15:16,bold:true,color:C.WHITE,align:'center',valign:above?'bottom':'top'});}};

 // ---- 1 TITLE
 {N++; const s=pres.addSlide(); s.background={color:C.BG};
  s.addShape('ellipse',{x:7.2,y:1.6,w:8.6,h:8.6,fill:{color:C.DEEP},line:{color:C.DEEP}});
  s.addShape('ellipse',{x:9.4,y:-1.6,w:3.6,h:3.6,fill:{color:C.GOLD,transparency:70},line:{color:C.GOLD,transparency:100}});
  s.addShape('ellipse',{x:-1.4,y:4.4,w:3.6,h:3.6,fill:{color:C.TEAL,transparency:85},line:{color:C.TEAL,transparency:100}});
  s.addImage({path:L+'dept_logo.png',x:0.4,y:0.22,w:1.62,h:0.5}); s.addImage({path:L+'cognia_badge.png',x:5.1,y:0.1,w:1.3,h:0.975}); s.addImage({path:L+'school_logo.png',x:12.35,y:0.18,w:0.62,h:0.62});
  txt(s,'MAWHIBA  ·  GRADE 9  ·  WEEK 10',{x:0.7,y:2.0,w:7,h:0.3,fontSize:14,bold:true,color:C.OR,charSpacing:3});
  txt(s,'Unit 3 · Activity '+cfg.act,{x:0.7,y:2.4,w:6.5,h:0.6,fontSize:26,fontFace:HEAD,color:C.TEAL,bold:true});
  txt(s,cfg.title2,{x:0.7,y:3.0,w:6.6,h:1.9,fontSize:42,bold:true,fontFace:HEAD,color:C.NAVY});
  txt(s,cfg.sub,{x:0.7,y:4.95,w:6.4,h:0.75,fontSize:18}); txt(s,'Mr Malek Thiab',{x:0.7,y:5.85,w:5,h:0.4,fontSize:18,bold:true});
  s.addImage({path:'fig/title_s.png',x:9.0,y:2.1,w:3.9,h:3.0}); txt(s,'Your crew leads. Your teacher facilitates.',{x:8.6,y:5.5,w:4.8,h:0.4,fontSize:16,color:C.WHITE,align:'center'});
  txt(s,'FAITH, RIGHTEOUSNESS AND WISDOM',{x:0.4,y:7.1,w:6.5,h:0.25,fontSize:10,bold:true,color:C.NAVY,charSpacing:3});
  s.addNotes(NOTES[cfg.nk].title); }
 // ---- 2 JOURNEY
 {N++; const s=pres.addSlide(); s.background={color:C.DEEP};
  s.addShape('ellipse',{x:-1.2,y:5.0,w:3.8,h:3.8,fill:{color:C.TEAL,transparency:80},line:{color:C.TEAL,transparency:100}}); s.addShape('ellipse',{x:10.8,y:-1.2,w:3.6,h:3.6,fill:{color:C.GOLD,transparency:82},line:{color:C.GOLD,transparency:100}});
  s.addImage({path:L+'dept_logo_white.png',x:0.4,y:0.22,w:1.62,h:0.5}); s.addImage({path:L+'school_logo_white.png',x:12.35,y:0.18,w:0.62,h:0.62});
  txt(s,'Your journey',{x:0.6,y:0.95,w:12,h:0.8,fontSize:40,bold:true,fontFace:HEAD,color:C.WHITE}); txt(s,cfg.journeyLine,{x:0.6,y:1.7,w:12,h:0.4,fontSize:18,color:'BFD8D5'});
  stationMap(s,false); if(cfg.need) txt(s,cfg.need,{x:0.6,y:6.35,w:12.1,h:0.6,fontSize:15,color:'BFD8D5'});
  txt(s,'FAITH, RIGHTEOUSNESS AND WISDOM',{x:4.4,y:7.1,w:4.5,h:0.25,fontSize:10,bold:true,color:C.WHITE,align:'center',charSpacing:3});
  s.addNotes(NOTES[cfg.nk].journey); }
 cfg.slides(Object.assign({pres,slide,card,lab,txt,M,Mc,bullets,numbered,C,IDX,NOTES,sh,HEAD,FONT,chips,whatif},{get N(){return N;}}));
 return pres.writeFile({fileName:cfg.raw}).then(()=>console.log('ok',cfg.raw,N));
}

const A2=(X)=>{const {slide,card,lab,txt,M,Mc,bullets,numbered,C,pres,whatif,IDX}=X; const NT=X.NOTES.a1;
 const gold=(s,t,x,y,w=4)=>txt(s,t,{x,y,w,h:0.3,fontSize:12,bold:true,color:C.GOLD,charSpacing:2});
 const doneBox=(s,x,y,w,h,t)=>{card(s,x,y,w,h); lab(s,'DONE WHEN',x+0.25,y+0.1); txt(s,t,{x:x+0.25,y:y+0.38,w:w-0.5,h:h-0.45,fontSize:14});};
 // ---- Station 1: Task 1
 {const s=slide('Task 1: match the paired variables',0,NT.t1);
  const CARDS=['Number of people in a lift','Total weight of passengers','Temperature','Seedling growth','Time in months','Children’s heights','Mileage','Petrol consumption','Number of TVs','Life span','Time in hours','Virus multiplication','Time in years','Radioactive decay','Pressure','Wind speed','Amount of fertiliser applied to a crop whilst growing','The crop yield produced'];
  const order=[2,13,0,9,6,17,4,3,10,15,8,1,14,5,12,11,16,7];
  card(s,0.5,1.95,8.1,4.35); lab(s,'EIGHTEEN CARDS  ·  NINE PAIRS',0.8,2.03,6);
  order.forEach((ix,i)=>{const x=0.75+(i%6)*1.3,y=2.4+Math.floor(i/6)*1.28; s.addShape('roundRect',{x,y,w:1.22,h:1.15,rectRadius:0.08,fill:{color:i%2?'E8F4F2':'FFF1C9'},line:{color:i%2?C.TEAL:C.GOLD,width:1.25}});
   txt(s,CARDS[ix],{x:x+0.06,y:y+0.04,w:1.1,h:1.07,fontSize:CARDS[ix].length>30?8.5:10.5,bold:true,color:C.NAVY,align:'center',valign:'middle'});});
  card(s,8.8,1.95,4.0,2.45,C.DEEP); gold(s,'TASK 1  ·  PAIRS, THEN FOURS',9.05,2.03,3.6);
  txt(s,'Match the cards into pairs. One card is the independent variable, one is the dependent variable. Explain the context you chose.',{x:9.05,y:2.4,w:3.5,h:1.9,fontSize:14,color:C.WHITE});
  card(s,8.8,4.55,4.0,1.75); lab(s,'THE TWO QUESTIONS',9.05,4.63,3.5);
  txt(s,bullets(['Independent: “What do I change?”','Dependent: “What do I observe?”'],14,6),{x:9.05,y:4.95,w:3.5,h:1.3,fontSize:14});
  whatif(s,0.5,6.4,12.3,0.62,'');
  txt(s,'What if a card could go with more than one partner? Find a card with two possible partners and explain each context.',{x:3.1,y:6.5,w:9.5,h:0.45,fontSize:14,valign:'middle'}); }
 // ---- Station 2a: three graphs
 {const s=slide('Task 2: three graphs, three kinds of relationship',1,NT.t2);
  const G=[['A','car','Hiring a car in Jeddah','SAR 280 a day, first 100 km included, then SAR 0.80 for each extra km.'],['B','spr','Stretching a spring','Masses are added to a spring and its length is measured with a ruler.'],['C','fer','Fertiliser on date palms','A farm in Al-Ahsa records fertiliser used and dates harvested per palm.']];
  G.forEach(([k,f,t,c],i)=>{const x=0.5+i*4.15,y=1.95; card(s,x,y,4.0,3.75); txt(s,k,{x:x+0.15,y:y+0.08,w:0.4,h:0.4,fontSize:20,bold:true,fontFace:'Cambria',color:C.OR});
   txt(s,t,{x:x+0.6,y:y+0.12,w:3.3,h:0.35,fontSize:15,bold:true,fontFace:'Cambria',color:C.NAVY}); s.addImage({path:'fig/th_'+f+'_s.png',x:x+0.3,y:y+0.55,w:3.4,h:3.4*2.9/4.0}); txt(s,c,{x:x+0.2,y:y+0.55+3.4*2.9/4.0+0.02,w:3.6,h:0.6,fontSize:10.5,color:'3F4B49'});});
  card(s,0.5,5.85,12.3,1.1,C.DEEP); gold(s,'USE THIS VOCABULARY',0.8,5.92,5);
  ['exact linear relationship','inexact linear relationship','experimental errors','limited assumptions','complex assumptions'].forEach((t,i)=>{const x=0.8+i*2.4; s.addShape('roundRect',{x,y:6.3,w:2.3,h:0.5,rectRadius:0.25,fill:{color:C.WHITE},line:{color:C.GOLD,width:1.5}}); txt(s,t,{x,y:6.3,w:2.3,h:0.5,fontSize:11,bold:true,color:C.NAVY,align:'center',valign:'middle'});}); }
 // ---- Station 2b: read the spring graph
 {const s=slide('Task 2: how exact is the spring graph?',1,NT.t3);
  card(s,0.5,1.95,6.2,4.55); lab(s,'GRAPH B  ·  A LINE THROUGH THE SPRING DATA',0.8,2.03,5.6); s.addImage({path:'fig/spr_fit_s.png',x:1.0,y:2.3,w:4.6,h:4.6*4.2/5.6}); Mc(s,'sprL',3.6,5.78,1.0,2.4);
  card(s,6.9,1.95,5.9,2.55,C.DEEP); gold(s,'DO THIS',7.2,2.03);
  txt(s,numbered(['Do the dots lie exactly on the line? Say what that means.','Read the gradient and the intercept from the line.','Name one source of experimental error.','Name one limited assumption about the spring.'],3),{x:7.2,y:2.38,w:5.4,h:2.1,fontSize:13,color:C.WHITE});
  whatif(s,6.9,4.65,5.9,0.95,'');
  txt(s,'What if you hang 5 kg on this spring? Use the line to predict, then decide whether to trust it.',{x:7.15,y:5.0,w:5.5,h:0.6,fontSize:13});
  doneBox(s,6.9,5.75,5.9,0.75,'You can name the relationship, give a reason, and interpret the gradient and intercept.'); }
 // ---- Station 3: judge the claims
 {const s=slide('Judge the claims: true, false or sometimes?',2,NT.claims);
  const CL=[['CLAIM A','If the dots do not lie exactly on a line, there is no linear relationship.','Look again at graph B.','Does a model need to touch every dot to be useful?'],['CLAIM B','Only one way of pairing the cards is correct.','Find a card with two possible partners.','Did I say which context I chose?'],['CLAIM C','The spring line is reliable for any mass.','Put 5000 g into the line.','Does the spring still behave the same far beyond the readings?']];
  CL.forEach(([t,c,test,asm],i)=>{const x=0.5+i*4.15,y=1.95; card(s,x,y,4.0,4.2); txt(s,t,{x:x+0.25,y:y+0.15,w:3.5,h:0.28,fontSize:12,bold:true,color:C.OR,charSpacing:2}); txt(s,c,{x:x+0.25,y:y+0.48,w:3.5,h:0.95,fontSize:16,bold:true,fontFace:'Cambria',color:C.NAVY});
   txt(s,'TEST IT',{x:x+0.25,y:y+1.5,w:3,h:0.25,fontSize:10,bold:true,color:'6B7977',charSpacing:2}); txt(s,test,{x:x+0.25,y:y+1.75,w:3.5,h:0.55,fontSize:13});
   ['TRUE','FALSE','SOMETIMES'].forEach((v,j)=>{const px=x+0.25+j*1.2; s.addShape('roundRect',{x:px,y:y+2.4,w:1.12,h:0.36,rectRadius:0.18,fill:{color:C.WHITE},line:{color:C.NAVY,width:1.5}}); txt(s,v,{x:px,y:y+2.4,w:1.12,h:0.36,fontSize:9.5,bold:true,color:C.NAVY,align:'center',valign:'middle'});});
   txt(s,'Because ........................................',{x:x+0.25,y:y+2.88,w:3.5,h:0.3,fontSize:12,color:'6B7977'});
   s.addShape('roundRect',{x:x+0.2,y:y+3.35,w:3.6,h:0.72,rectRadius:0.1,fill:{color:'FFF1C9'},line:{color:C.GOLD,width:1.5}}); txt(s,'ASSUMPTION CHECK',{x:x+0.35,y:y+3.4,w:3.3,h:0.22,fontSize:9,bold:true,color:C.OR,charSpacing:2}); txt(s,asm,{x:x+0.35,y:y+3.64,w:3.3,h:0.4,fontSize:11.5});});
  card(s,0.5,6.3,12.3,0.65,C.DEEP); txt(s,'Which graph gave you the strongest evidence: an exact one, an inexact one, or one with complex assumptions? What made you decide?',{x:0.8,y:6.3,w:11.7,h:0.65,fontSize:15,color:C.WHITE,valign:'middle'}); }
 // ---- Station 4: apply and present
 {const s=slide('Apply and present: a fast charger near Jeddah',3,NT.apply);
  card(s,0.5,1.95,7.3,4.95); lab(s,'MODEL VALUES (ILLUSTRATIVE, NOT REAL CHARGER DATA)',0.8,2.03,6.8);
  txt(s,'An electric car is plugged into a fast charger. The battery charge is recorded every 10 minutes.',{x:0.8,y:2.35,w:6.7,h:0.75,fontSize:14});
  s.addImage({path:'fig/chg_s.png',x:0.6,y:3.2,w:4.0,h:4.0*4.2/5.9});
  txt(s,numbered(['Which variable is independent? Which is dependent?','Use the first five readings: find a line and its equation.','Predict the charge after 25 minutes.','What if the car stays 90 minutes? Is the line still sensible? Say exact or inexact, and why.'],4),{x:4.75,y:3.2,w:2.95,h:3.65,fontSize:12});
  card(s,8.0,1.95,4.8,2.15,C.DEEP); gold(s,'PRESENT  ·  1 MINUTE EACH',8.3,2.05,4.4);
  txt(s,bullets(['Two reporters share evidence: a graph, an equation or numbers.','Share one What if...? your crew asked and one idea that is your own.'],14,6),{x:8.3,y:2.4,w:4.3,h:1.6,fontSize:14,color:C.WHITE});
  card(s,8.0,4.25,4.8,2.65); lab(s,'MY MAWHIBA RECORD: TICK A VALUE',8.3,4.33,4.4);
  ['Inquiry','Risk taking','Perseverance','Collaboration','Concern for society'].forEach((t,i)=>{const x=8.3+(i%2)*2.25,y=4.7+Math.floor(i/2)*0.62; s.addShape('rect',{x,y:y+0.1,w:0.26,h:0.26,fill:{color:C.WHITE},line:{color:C.NAVY,width:1.5}}); txt(s,t,{x:x+0.35,y,w:1.85,h:0.46,fontSize:12,bold:true,color:C.NAVY,valign:'middle'});});
  txt(s,'Add today’s evidence to your cumulative record.',{x:8.3,y:6.4,w:4.3,h:0.45,fontSize:12,color:'3F4B49'}); }
};
const cfg={file:'Mawhiba Unit 3 Activity 2 Paired Variables presentation',raw:'raw_U3A2.pptx',act:2,nk:'a1',title2:'Paired Variables',titleKey:null,
 sub:'Which variable do I change, and how exact is the relationship?',
 stations:[['Match it','8 min'],['Read it','14 min'],['Judge it','8 min'],['Apply and present','10 min']],
 journeyLine:'Four stations, 40 minutes, and plenty of What if...? Each station zooms in as you arrive.',
 need:'You will need: the worksheet, a clear ruler, a sharp pencil, and a spreadsheet or GeoGebra if you have one.',
 slides:A2};
(async()=>{await build(cfg);})();
